public class Main{static long xsNext(long x){x^=x<<13;x^=x>>>7;x^=x<<17;return x;} static StringBuilder text=new StringBuilder(); static long gen(int depth, long seed){ long r=xsNext(seed); if(depth==0||(r&3)==0){ if(((r>>>8)&1)==0){ long n=3+Long.remainderUnsigned(r,12); for(long i=0;i<n;i++){r=xsNext(r); text.append((char)('a'+Long.remainderUnsigned(r,26)));} } else text.append(Long.remainderUnsigned(r>>>16,100000)); text.append(' '); return r; } text.append('('); long kids=2+Long.remainderUnsigned(r>>>24,4); for(long k=0;k<kids;k++) r=gen(depth-1,r); text.append(')'); text.append(' '); return r; } public static void main(String[]a){ long seed=12345; for(int i=0;i<100;i++) seed=gen(4,seed); long h=1469598103934665603L; for(int i=0;i<text.length();i++) h=(h ^ text.charAt(i)) * 1099511628211L; System.out.println(text.length()); System.out.println(Long.toUnsignedString(h));}}